          "detailMarkdown": "## 1710 東聯 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（57 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 1、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2026Q1 合併營收為 53.46 億元，較前季維持在 50 億元以上的單季水準。\n- 2026Q1 歸屬東聯合併損失約 1.3 億元，EPS 為 -0.15 元；簡報圖示亦列示 2025 年為虧損。\n- 2026/3/31 合併總資產約 369 億元，負債約 237 億元，權益約 132 億元，權益比 36%，每股淨值 12.4 元。\n- 三大事業營收比重方面，乙二醇事業約 61%，特化事業約 31%，氣體事業約 8%。\n- 管理層提到過去幾季在戰爭、油價與原料供應波動下，營運先受壓抑，後續隨產品售價調整而改善。\n\n### 展望與成長利基\n- 公司將持續推進電子化學品、AI 應用材料與綠色化學三條線，作為未來主要成長方向。\n- 電子級溶劑已切入台灣與中國大陸客戶，並規劃拓展日本市場；其中 DB 產品成長性被特別點出。\n- 半導體應用方向涵蓋清洗、顯影、光阻剝離、先進封裝與 CMP 相關配方，並提到與 2nm/3nm、HBM、CoWoS 等應用連結。\n- 高純度 CO2、電子級 CO2 與半導體級 CO2 開發被納入循環經濟與高值化布局。\n- 氣體新廠預計 2026 年底啟用，管理層認為可提升供應效率並改善成本結構。\n\n### 產品、客戶與市場位置\n- 公司定位仍以乙二醇、氣體與特用化學為三大事業體，並明確強調往半導體、電子材料與 AI 新材料延伸。\n- 會中多次提及「半導體元年」與「電子應用化學品／AI 應用材料」布局，顯示轉型方向已列為中期重點。\n- Q&A 聚焦在電子級溶劑、半導體清洗材料、EOD 衍生物、以及產能／客戶應用分布。\n- 管理層提到過去幾季在戰爭、油價與原料供應波動下，營運先受壓抑，後續隨產品售價調整而改善。\n- 公司將持續推進電子化學品、AI 應用材料與綠色化學三條線，作為未來主要成長方向。\n- 電子級溶劑已切入台灣與中國大陸客戶，並規劃拓展日本市場；其中 DB 產品成長性被特別點出。\n\n### 風險與不確定性\n- 管理層重申未發布財測，且未來表現可能受市場需求、價格波動、競爭、匯率與供應鏈等因素影響。\n- 原料端受油價、乙烯價格與地緣政治影響明顯，且下游售價反應常有落後性。\n- 乙烯供應曾受設備故障與外部供應中斷影響，顯示原料穩定性仍是營運變數。\n- 特化與電子級產品仍處於擴張、認證與客戶導入階段，實際放量時程受客戶產線與需求節奏影響。\n- 氣體廠建置與舊廠轉換涉及工程進度與投產時程，仍具執行風險。\n- **需人工確認**：簡報頁 4 的資本額為 **88.6 億元**，英文版寫作 **NT$ 8,857 million**，數字一致但單位表述需統一。\n- **需人工確認**：簡報頁 5／英文版頁 5 對高雄乙烯儲槽與液氨儲槽完工時點的描述，與口頭轉錄一致，但轉錄中「乙烯廚槽／億安廚槽」疑似語音辨識誤差，應校正為「乙烯儲槽／液氨儲槽」。\n- **需人工確認**：簡報頁 11 顯示 2025 年歸屬東聯合併損益為 **(8.9) 億元**、EPS **(1.01) 元**；轉錄提到 2025 年為虧損且 2026Q1 為 **(1.3) 億元 / -0.15 元**，一致但仍建議確認單位與四捨五入方式。\n\n### Q&A 與管理層口氣\n- 電子級溶劑部分：目前提及 MEA、TEA、DB 等產品，主要供電子材料客戶配方使用，再供應半導體相關用途。\n- DB 產品：月銷量約 160 噸，管理層提到客戶擴產後，未來一年到一年半有機會成長超過 100%。\n- 大宗產品應用：EG 主要供化纖與 PET；EO 供自用及外部客戶；EA/EB/EC/EOD 則分別對應塗料、農藥、塑膠、清洗劑、電解液等多元應用。\n- 會中表示部分工業級產品並非東聯唯一供應商，但半導體電子級部分被描述為少數可供應來源。\n- 提到高純度 EC 產能已於去年完工，用於鋰電池電解液相關應用。\n\n### 評分利基點\n- 加分主因：公司定位仍以乙二醇、氣體與特用化學為三大事業體，並明確強調往半導體、電子材料與 AI 新材料延伸。；管理層提到 2025 年完成高雄乙烯儲槽、2026 年完成液氨儲槽，有助原料採購彈性與成本管理。；氣體廠新建工程已啟動，預計 2026 年底投產，目標取代效率較低的既有氣體廠並提升產量、降低耗電。。\n- 扣分或保留：管理層重申未發布財測，且未來表現可能受市場需求、價格波動、競爭、匯率與供應鏈等因素影響。；原料端受油價、乙烯價格與地緣政治影響明顯，且下游售價反應常有落後性。；乙烯供應曾受設備故障與外部供應中斷影響，顯示原料穩定性仍是營運變數。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
