          "detailMarkdown": "## 6988 威力暘-創 深度法說分析\n\n### 一頁結論\n- 展望評價：正面看好（72 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 4、保守訊號 1。\n- 判讀：正向訊號較集中，通常代表公司對需求、訂單或產品組合的能見度較高。仍要確認這些動能是否能轉成營收與毛利。 \n\n### 營運與財務重點\n- 2026Q1 營收 **1.69 億元**，年減 **25%**；營業毛利 **5,279 萬元**，年減 **20%**。\n- 2026Q1 毛利率 **31%**，較 2025Q1 的 **30%** 提升 1 個百分點。\n- 2026Q1 營業淨損 **189 萬元**，稅後淨損 **256 萬元**；EPS **-0.05 元**。\n- 2026/03/31 資產總額 **11.42 億元**、權益總額 **7.13 億元**、負債比率 **38%**。\n- 現金及金融資產 **3.41 億元**；流動比率 **320%**，公司在會中描述短期償債能力穩定。\n\n### 展望與成長利基\n- 2026 上半年：推進 **DENSO 新平台量產認可**、**AI 散熱 BMC 模組**、**AI 液冷電控合作**。\n- 2026 下半年：規劃 **次世代 ADAS ECU 設計導入**、**無人載具電控切入**、**滁州廠豐田體系在地化協作**。\n- 2027 年：期望**多元化業務貢獻度提升**，並持續拓展國際客戶與新市場。\n- AI 散熱產品在會中被定位為**第二成長曲線**，但公司表示 2026 年仍將**以車載業務為主**。\n- 管理層提到 AI 散熱產品具**較高毛利潛力**，但目前仍屬量產初期、營收占比偏低。\n\n### 產品、客戶與市場位置\n- 會中重點新增兩條成長曲線：**AI 散熱/液冷電控**與**無人載具/航太電控**。\n- 2026 年第一季營收年減，主因為**中端客戶需求減少**；但毛利率較去年同期小幅提升。\n- Q&A 聚焦在**AI 散熱產品營收占比、毛利率與 2026 年貢獻**，公司回應目前仍在量產初期、占比偏低。\n- 2026 上半年：推進 **DENSO 新平台量產認可**、**AI 散熱 BMC 模組**、**AI 液冷電控合作**。\n- 2027 年：期望**多元化業務貢獻度提升**，並持續拓展國際客戶與新市場。\n- AI 散熱產品在會中被定位為**第二成長曲線**，但公司表示 2026 年仍將**以車載業務為主**。\n\n### 風險與不確定性\n- 營收仍受**車用客戶需求變動**影響，2026Q1 已反映中端客戶需求下滑。\n- 新業務如 **AI 液冷電控、無人載具電控** 仍在導入與驗證階段，商業化時程存在不確定性。\n- 公司提及 **ISO 21434** 認證仍在 SGS 審核中，未完成前屬流程推進階段。\n- 轉錄與簡報皆提到前瞻性陳述、實際結果可能與預期不同，具有外部不確定性。\n- 車用電子、AI 基礎設施與航太應用皆涉及高認證門檻與客戶驗證流程，導入周期可能較長。\n- **需人工確認**：轉錄中提到公司「**在取 2024 年的部分在創新版的上市**」，但簡報頁面顯示公司代號為 **6988 創新版**，上市/掛牌時間表述與常識可能不一致。\n- **需人工確認**：轉錄寫「**威力揚**／威力洋」等發音變體，簡報公司名為 **威力暘-創**；為語音辨識誤差，正式名稱以簡報為準。\n- **需人工確認**：轉錄提及「**ISO6B**」，簡報為 **ISO 26262 / ASIL C**，疑似口語辨識錯誤。\n\n### Q&A 與管理層口氣\n- 2026 年第一季營收年減，主因為**中端客戶需求減少**；但毛利率較去年同期小幅提升。\n- Q&A 聚焦在**AI 散熱產品營收占比、毛利率與 2026 年貢獻**，公司回應目前仍在量產初期、占比偏低。\n- 2026Q1 毛利率 **31%**，較 2025Q1 的 **30%** 提升 1 個百分點。\n\n### 評分利基點\n- 加分主因：公司主軸仍以**車用電子 ECU/電控模組**為核心，並強調從單一供應商轉向**平台級策略夥伴**。；會中重點新增兩條成長曲線：**AI 散熱/液冷電控**與**無人載具/航太電控**。；2026 年第一季營收年減，主因為**中端客戶需求減少**；但毛利率較去年同期小幅提升。。\n- 扣分或保留：營收仍受**車用客戶需求變動**影響，2026Q1 已反映中端客戶需求下滑。；新業務如 **AI 液冷電控、無人載具電控** 仍在導入與驗證階段，商業化時程存在不確定性。；公司提及 **ISO 21434** 認證仍在 SGS 審核中，未完成前屬流程推進階段。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
