          "detailMarkdown": "## 2762 世界健身-KY 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（64 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 2、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2026Q1 營收為 **NT$28.1億元**，年增 **9.4%**、季減 **2.3%**。\n- 毛利率 **21.8%**，營業利益 **NT$3.01億元**，營業利益率 **10.7%**。\n- 稅後淨利 **NT$2.19億元**，EPS **NT$2.01**；簡報顯示獲利年增幅度明顯。\n- 現金流方面，營運活動現金流入 **NT$8.16億元**；期末現金 **NT$9.45億元**。\n- 資產負債表摘要顯示資產總額 **NT$183.89億元**，負債總額 **NT$157.23億元**，權益總額 **NT$26.66億元**。\n\n### 展望與成長利基\n- 公司規劃四大成長動能：**Pilates 課程上線、零售銷售強化、長壽逆齡平台、HYROX 聯名合作**。\n- 泰國市場預計 2026 年啟動 **2 家據點**，並規劃後續擴點；2027 年目標再增加 **4 家**。\n- 管理層表示泰國採取「先建立標準與複製系統、再逐步擴張」的模式，預期先完成預售與營運驗證。\n- Pilates 目前先導入部分門市，第二階段持續擴大，方向為逐步覆蓋更多店點。\n- 長壽逆齡平台、保健食品、DNA/健康管理延伸服務等，皆被視為後續可擴充的衍生機會。\n\n### 產品、客戶與市場位置\n- 泰國市場預計 2026 年啟動 **2 家據點**，並規劃後續擴點；2027 年目標再增加 **4 家**。\n- 新平台涉及健康、個資與法規遵循，雖稱資料由醫療機構平台處理，但仍存在執行與合作風險。\n\n### 風險與不確定性\n- 轉錄與簡報存在部分數字、名詞與門市數量差異，需人工確認後再引用。\n- 泰國展店仍在前期建置與教育訓練階段，實際開幕時程、會員招募與損益貢獻仍具不確定性。\n- 管理層提到第三季電費通常較高，成本結構可能帶來季節性波動。\n- 新平台涉及健康、個資與法規遵循，雖稱資料由醫療機構平台處理，但仍存在執行與合作風險。\n- 公司提及 M&A、加盟、海外擴張等選項，但尚未有可揭露之具體對象或交易進度。\n- **需人工確認：** 簡報英文版列示營業利益 **NT$300mn**、毛利率增減數字與中文簡報/口語敘述略有差異；中文簡報為 **NT$3.01億元**、英文版為 **NT$300mn**，差異可屬四捨五入但仍建議核對。\n- **需人工確認：** 全球據點數量在轉錄中提到「World Gym 全球 288 家、10 個國家」，簡報頁面僅列出 **Company Owned + JV: 138 / Franchise: 150**，但未明確加總口徑與是否含台灣。\n- **需人工確認：** 轉錄提到台灣直營/門市數為 **140 家**、會員 **49萬/50萬** 等，簡報頁面寫 **138** 與 **50萬名會員**，口徑不一致。\n\n### Q&A 與管理層口氣\n- 毛利率 **21.8%**，營業利益 **NT$3.01億元**，營業利益率 **10.7%**。\n- 管理層提到第三季電費通常較高，成本結構可能帶來季節性波動。\n- **需人工確認：** 簡報英文版列示營業利益 **NT$300mn**、毛利率增減數字與中文簡報/口語敘述略有差異；中文簡報為 **NT$3.01億元**、英文版為 **NT$300mn**，差異可屬四捨五入但仍建議核對。\n\n### 評分利基點\n- 加分主因：公司強調 Q1 營運表現維持成長，屬訂閱型經營模式下的累積成果。；會中主軸聚焦於：Q1財務表現、現金流與配息、全球布局與泰國展店、以及新成長動能。；公司規劃四大成長動能：**Pilates 課程上線、零售銷售強化、長壽逆齡平台、HYROX 聯名合作**。。\n- 扣分或保留：轉錄與簡報存在部分數字、名詞與門市數量差異，需人工確認後再引用。；泰國展店仍在前期建置與教育訓練階段，實際開幕時程、會員招募與損益貢獻仍具不確定性。；管理層提到第三季電費通常較高，成本結構可能帶來季節性波動。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
