          "sourceReport": "../法說整理/reports/ir_summary_2026-06-09.md",
          "detailMarkdown": "## 6174 安碁 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（64 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 2、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 公司自述成立約 **35 年**，全球員工約 **260 人**，主要生產基地在**台中潭子**。\n- 2026 年 Q1 營收組合口述為：**車用 54.44%**、工控 3.03%、PC/消費 10.7%、網通 4.3%、heavy label 7.63%、其他 9.9%。\n- 2026 年 Q1 提及 **Oscillator 營收占比 39.58%**，並表示其毛利貢獻較高；研發費用約 **7%~8%**。\n- 2026 年 Q1 提及資產約 **11 億元**、每股淨值 **13.27 元**、負債比率 **33.96%**；5 月累計合併營收年增 **21.41%**。\n- 2025~2026 年小尺寸產能與高頻研發設備相關資本支出合計約 **2.18 億元**；交期由先前約 4 個月回復至 **6~8 週**。\n\n### 展望與成長利基\n- 車用仍被視為主要成長引擎，管理層認為其需求與開案動能在下半年相對較強。\n- AI 與資料中心相關產品已開始送樣，但目前仍屬**導入初期**，公司並未明確設定短期占比目標。\n- 光通訊相關頻點已布局 **50MHz、156.25MHz、212.5MHz、312.5MHz** 等，部分產品預計下半年或年底前推進量產/送樣。\n- 無人機、工控、智慧醫療等應用也被提及為中長期機會，但目前仍以送樣與客戶驗證為主。\n- 公司提到希望在既有產能擴充 20% 的基礎上，帶動較高階產品的營收成長。\n\n### 產品、客戶與市場位置\n- 目前營收結構以**車用**為主，並持續布局**工控、PC/消費、網通、AI、光通訊、無人機**等新應用。\n- 會中多次提及**擴產、交期恢復、送樣轉量產**，顯示供應能力與產品組合調整是當前重點。\n- 簡報與口述均指出，車用與 AI、光通訊是未來主要成長方向，但部分新業務仍處於送樣與認證階段。\n- AI 與資料中心相關產品已開始送樣，但目前仍屬**導入初期**，公司並未明確設定短期占比目標。\n- 光通訊相關頻點已布局 **50MHz、156.25MHz、212.5MHz、312.5MHz** 等，部分產品預計下半年或年底前推進量產/送樣。\n- 無人機、工控、智慧醫療等應用也被提及為中長期機會，但目前仍以送樣與客戶驗證為主。\n\n### 風險與不確定性\n- **原物料價格上漲**與交期拉長，對成本與供應穩定性造成壓力。\n- **AI／光通訊／無人機**等新應用的認證週期較長，且需要客戶實測、approve，導入時間不易估算。\n- 新產品如光通訊、AI Server 目前仍面臨**客戶結構、供應鏈認證與交貨紀錄不足**等不確定性。\n- 主要 IC 依賴**外購且以日本供應商為主**，雖已有綁量機制，但仍受價格調整與供應條件影響。\n- 公司明確提到，部分應用的營收發酵可能較晚，短期貢獻仍有限。\n- **需人工確認**：語音轉錄中公司名稱多處寫作「安基科技／安記科技／安機」，與會議資訊「6174 安碁」及簡報英文「AKER」可能不一致。\n- **需人工確認**：口述提到的認證名稱「TOF 認可的 ISO2007」疑似有誤，與簡報僅見 Corporate Disclaimer，無法對照。\n- **需人工確認**：口述提到「2026 年 EQ / Q1 / 2026 年 Q1」多次混用，部分數字可能來自不同基準期間，需確認是否為同一季度。\n\n### Q&A 與管理層口氣\n- Q&A 中說明：AI Server 與光通訊可視為獨立追蹤項目，但若為既有客戶的延伸案，仍可能先歸在原本客群分類。\n- 針對光模組與 AI Server 的供應商結構，公司表示**光模組主要供應商偏日商**，AI Server 則**不全然以日商為主**。\n- 公司表示已與 IC 供應商採取**預付貨款、綁量一年**的合作方式，運作約三年，以降低斷料風險。\n- 無人機產品方面，管理層提到目前已有 **11 家客戶、18 個品點、57 個料號** 的送樣/導入記錄。\n- 公司澄清**沒有 MANs 產品**，理由是製程與既有晶振/Oscillator 製程不同。\n\n### 評分利基點\n- 加分主因：公司主軸聚焦於**高階時脈元件**，包含 **Crystal、Oscillator、TCXO/相關高頻應用**，並強調品質、服務與永續為核心。；管理層提到公司已從代工模式轉向**自有品牌為主**，品牌營收比重顯著提高。；會中多次提及**擴產、交期恢復、送樣轉量產**，顯示供應能力與產品組合調整是當前重點。。\n- 扣分或保留：**原物料價格上漲**與交期拉長，對成本與供應穩定性造成壓力。；**AI／光通訊／無人機**等新應用的認證週期較長，且需要客戶實測、approve，導入時間不易估算。；新產品如光通訊、AI Server 目前仍面臨**客戶結構、供應鏈認證與交貨紀錄不足**等不確定性。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
