          "detailMarkdown": "## 9904 寶成 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（58 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 2、保守訊號 1。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2026Q1 合併營收為 NT$630.92 億，年減 5.9%；前四個月自結合併營收約 NT$854 億，年減 3.5%。\n- 製鞋業務 2026Q1 營收 NT$397.33 億，年減 9.1%，占合併營收 63.0%。\n- 零售業務 2026Q1 營收 NT$230.89 億，年增 0.1%，占合併營收 36.6%。\n- 合併財報 2026Q1 稅後淨利 NT$22.30 億，EPS NT$0.76；轉錄提及認列南山人壽相關投資收益帶動業外改善。\n- 製鞋端 2026Q1 出貨 56.9 百萬雙，年減 8.1%；平均售價（ASP）年增 2.4%。\n- 裕元工業 2026Q1 營收 US$19.85 億，年減 2.2%；毛利率 21.7%，年減 1.2 個百分點；稅後淨利 US$35 百萬，年減 53.6%。\n- 寶勝國際 2026Q1 營收 RMB 50.51 億，年減 1.1%；毛利率 33.6%，營業淨利率 5.8%，稅後淨利 RMB 1.83 億。\n\n### 展望與成長利基\n- 製鞋業務方面，管理層表示第二季進入傳統旺季，且無印尼開齋節重疊因素，出貨雙數有機會較第一季回升。\n- 訂單能見度仍偏低，已確認訂單一般交期約 10–12 週，較短交期約 30–45 天。\n- ASP 主要仍取決於實際產品組合與客戶機型差異，公司續朝產品結構優化。\n- 製造端資本支出將延續印度新廠建置與印尼擴產規劃，並依客戶需求與工程進度動態調整。\n- 零售端持續觀察中國消費景氣與終端需求，並強化線上線下整合、庫存管理與品牌合作。\n\n### 產品、客戶與市場位置\n- ASP 主要仍取決於實際產品組合與客戶機型差異，公司續朝產品結構優化。\n- 製造端資本支出將延續印度新廠建置與印尼擴產規劃，並依客戶需求與工程進度動態調整。\n- 零售端持續觀察中國消費景氣與終端需求，並強化線上線下整合、庫存管理與品牌合作。\n- 全球總體經濟與地緣/政經情勢仍具不確定性，品牌客戶下單趨於審慎。\n- 關稅政策變動與美國相關貿易措施仍在演變中，後續對成本與接單的影響尚待觀察。\n- 製造端毛利率：管理層表示採「成本加成」報價機制，會視成本變化與訂單穩定度與客戶溝通。\n\n### 風險與不確定性\n- 全球總體經濟與地緣/政經情勢仍具不確定性，品牌客戶下單趨於審慎。\n- 製鞋端面臨短單化、產能排程錯位、人工成本上升等壓力，對毛利率形成影響。\n- 關稅政策變動與美國相關貿易措施仍在演變中，後續對成本與接單的影響尚待觀察。\n- 零售端主要營運地區消費需求回溫幅度尚不明確，管理層仍以「持續觀察」表述。\n- 原物料價格波動可能帶來時間差影響，即使採成本加成機制，仍不排除短期利潤受擾。\n- 轉錄中提及「南山人壽 IFRS 17 重編」對比較基期造成影響，財報可比性需留意。\n- 轉錄提及「寶盛/寶盛國際」多處，簡報正式名稱為「寶成/寶勝國際」；屬語音辨識或口誤，**需人工確認**。\n- 轉錄中出現「台星證券」，簡報與會議資訊為「台新證券」；**需人工確認**。\n\n### Q&A 與管理層口氣\n- 製鞋出貨與 ASP：Q2 因旺季及節慶干擾減少，出貨有望回升；但下半年能見度仍有限。\n- 製造端毛利率：管理層表示採「成本加成」報價機制，會視成本變化與訂單穩定度與客戶溝通。\n- 關稅分攤/退稅：僅提及持續關注政策變化，未揭露具體分攤比例或退稅安排。\n- 零售端展望：前四月營收年減幅度仍存在，但終端需求大致平穩，會持續優化通路與庫存。\n- 原物料波動：若價格大幅變動，將透過報價機制反應，但可能存在時間差。\n- 短單趨勢：部分品牌交期較短，但實際仍須以已確認訂單為準。\n\n### 評分利基點\n- 加分主因：管理層指出，第一季合併營收年減，主因為製鞋出貨動能放緩；零售則相對平穩。；合併財報 2026Q1 稅後淨利 NT$22.30 億，EPS NT$0.76；轉錄提及認列南山人壽相關投資收益帶動業外改善。；製造端資本支出將延續印度新廠建置與印尼擴產規劃，並依客戶需求與工程進度動態調整。。\n- 扣分或保留：全球總體經濟與地緣/政經情勢仍具不確定性，品牌客戶下單趨於審慎。；製鞋端面臨短單化、產能排程錯位、人工成本上升等壓力，對毛利率形成影響。；關稅政策變動與美國相關貿易措施仍在演變中，後續對成本與接單的影響尚待觀察。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
