          "detailMarkdown": "## 6951 青新-創 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（64 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 2、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2026Q1 營收 **209,781 仟元**，QoQ **-17%**、YoY **+21%**；毛利率 **60.89%**，維持高檔。\n- 2026Q1 營業利益 **84,570 仟元**、營業利益率 **40.31%**；稅後淨利 **68,438 仟元**，EPS **1.49 元**。\n- 現金流部分，Q1 營業活動淨現金流入 **80,853 仟元**，自由現金流 **45,779 仟元**。\n- 營收結構上，醫廢、事廢為主要來源；再利用與青新木等新事業收入規模仍相對小，但呈現成長。\n- 口述提到成本控制良好、毛利率維持高檔；2025 年與 2026 年截至 4 月的營收規模分別為 **8.66 億元**、**2.88 億元**。\n\n### 展望與成長利基\n- 醫療廢棄物與事業廢棄物清除業務，將持續透過品牌效應、客戶關係與服務版圖擴張來成長。\n- 未來重點包括：爭取公立醫療院所標案、開發生技業報廢品清除、科技廠廢液清除、地方政府石棉瓦清除專案。\n- 再利用業務將朝增加核准處理品項、優化製程、提升廢塑膠轉化率方向發展。\n- 空瓶回收處理廠（斗六廠）於 **2026/04 中旬正式投產**，2026 年以獲利為目標。\n- 青新木業務將爭取公共工程建材供應商資格，並拓展代工與同業合作。\n\n### 產品、客戶與市場位置\n- 公司定位為醫療廢棄物、事業廢棄物清除與資源循環整合業者，並延伸至再利用處理、空瓶回收、塑木建材與廢水處理。\n- 管理層強調本業具長期深耕與客戶基礎，並透過循環再利用事業擴大第二成長曲線。\n- 醫療廢棄物與事業廢棄物清除業務，將持續透過品牌效應、客戶關係與服務版圖擴張來成長。\n- 未來重點包括：爭取公立醫療院所標案、開發生技業報廢品清除、科技廠廢液清除、地方政府石棉瓦清除專案。\n- 口述中提及公司為循環經濟與環保政策受惠產業之一，並提到 AI 供應鏈帶動電子廠產能增加，間接有利廢棄物清運需求。\n\n### 風險與不確定性\n- 公司明確揭露：簡報內部分資訊屬前瞻性內容，實際結果可能受無法控制之風險影響。\n- 簡報財務數字未經會計師查核或核閱，僅供參考。\n- 事廢業務受石綿瓦清運量、風災與專案時點影響，收入波動較大。\n- 勞務收入受政府標案開標與執行時點影響，短期可見度較低。\n- 新事業（再利用、空瓶回收、青新木）仍在擴產或試營運階段，後續量產與獲利穩定性尚待觀察。\n- **需人工確認：會議轉錄中多次出現公司名稱誤植為「清新／欣興」**，應以簡報與公司名稱 **「青新-創／Chin Hsin」** 為準。\n- **需人工確認：轉錄開場提及「2025年Q1」**，但本場會議與簡報主題為 **2026年第一季**，疑似口誤。\n- **需人工確認：轉錄提到「EPS 1.27」**，簡報表列為 **Q4/25 EPS 1.13**，數字不一致。\n\n### Q&A 與管理層口氣\n- 未揭露正式 Q&A 逐題問答內容。\n- 口述中提及公司為循環經濟與環保政策受惠產業之一，並提到 AI 供應鏈帶動電子廠產能增加，間接有利廢棄物清運需求。\n- 口述提到公司員工流動率低、長期累積專業同仁，支撐高毛利結構。\n- 口述提到未來數年仍以穩定成長為主，不預期短期大幅爆發。\n- 會議結尾為管理層致謝，未見其他補充資料。\n\n### 評分利基點\n- 加分主因：管理層強調本業具長期深耕與客戶基礎，並透過循環再利用事業擴大第二成長曲線。；簡報與口述皆強調公司採 **穩健成長** 與 **逐步擴張** 的節奏，非短期爆發型業務。；2026Q1 營收 **209,781 仟元**，QoQ **-17%**、YoY **+21%**；毛利率 **60.89%**，維持高檔。。\n- 扣分或保留：公司明確揭露：簡報內部分資訊屬前瞻性內容，實際結果可能受無法控制之風險影響。；簡報財務數字未經會計師查核或核閱，僅供參考。；事廢業務受石綿瓦清運量、風災與專案時點影響，收入波動較大。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
