          "detailMarkdown": "## 2887 台新新光金 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（50 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 0、保守訊號 0。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- 1Q26 金控稅後淨利 **211 億元**，較 1Q25 的 **47 億元**顯著增加；主要來自銀行、壽險與證券子公司貢獻提升。\n- 金控總資產 **9.06 兆元**、股東權益 **5,992 億元**、每股淨值 **21.60 元**；資產與權益規模較去年同期擴大。\n- 台新銀行 1Q26 稅後淨利 **63 億元**；新光銀行 **22 億元**；合併銀行獲利 **86 億元**。\n- 新光人壽 1Q26 稅後淨利 **119 億元**；台新證券 1Q26 稅後淨利 **16 億元**；元富證券 **15 億元**。\n- 銀行面，台新銀行 1Q26 總放款 **1.989 兆元**、年增 **11.3%**，NIM **1.48%**；存款 **2.636 兆元**，活存比 **51.1%**。\n\n### 展望與成長利基\n- 管理層對 2026 年銀行放款成長維持 **高個位數**看法，其中法金預期雙位數、個金高個位數；信用成本維持原先預估區間。\n- 台新銀行全年手續費收入維持 **雙位數成長**目標；新光銀行手續費收入則維持 **中個位數成長**看法。\n- 壽險方面，年度新契約 CSM 目標維持 **700 億元**；商品策略將持續聚焦高保障、長年期與健康險等核心商品。\n- 管理層表示壽險避險比率未來約落在 **40%～50%** 區間，並持續觀察市場與避險工具成本。\n- 關於人壽股利上繳，管理層表示需待主管機關細則確定後再評估，現階段未納入預估。\n\n### 產品、客戶與市場位置\n- 會中也補充 2026 年經濟與市場展望，並多次回答股利、增資、系統整併、避險與 CSM 等問題。\n- 管理層表示壽險避險比率未來約落在 **40%～50%** 區間，並持續觀察市場與避險工具成本。\n- 外部總經不確定性仍高，簡報與轉錄均提及 **中東地緣政治衝突**、通膨與利率路徑變化，可能影響市場波動。\n- 壽險投資與避險結果受匯率、利率與市場價格變動影響；1Q26 雖有正利差，但後續表現仍取決於金融市場走勢。\n\n### 風險與不確定性\n- 外部總經不確定性仍高，簡報與轉錄均提及 **中東地緣政治衝突**、通膨與利率路徑變化，可能影響市場波動。\n- 壽險投資與避險結果受匯率、利率與市場價格變動影響；1Q26 雖有正利差，但後續表現仍取決於金融市場走勢。\n- 1Q26 起採 **IFRS 17**，與過去 IFRS 4 期間的損益、CSM、投資收益等指標可比性有限。\n- 台新證券與元富證券合併後曾出現系統調整問題；管理層表示目前已趨穩定，但整併初期的營運中斷風險仍需留意。\n- 金控對子公司資本狀況持續監控；目前除期貨孫公司已注資 **8 億元**外，其他子公司暫無增資計畫。\n- **需人工確認**：轉錄中一度口誤將「台新人壽與新光人壽」說成「台新/台新人壽」，但簡報與後續內容一致為 **台新人壽與新光人壽於 2026/01/01 合併**。\n- **需人工確認**：轉錄提到「台股指數持續創新高」與「2026 年台灣經濟成長率有望超過 10%」屬口語敘述，簡報未提供對應數字或正式預測來源。\n- **需人工確認**：轉錄中提及壽險「adjusted/recurrent yield」數字如 **3.42%**、淨值比約 **9%**、OCI 已實現利益與調整後獲利 **256 億元**，簡報內相關頁面可對應部分數字但口語說明較多，建議逐頁再核對。\n\n### Q&A 與管理層口氣\n- 管理層對 2026 年銀行放款成長維持 **高個位數**看法，其中法金預期雙位數、個金高個位數；信用成本維持原先預估區間。\n- 管理層表示壽險避險比率未來約落在 **40%～50%** 區間，並持續觀察市場與避險工具成本。\n\n### 評分利基點\n- 加分主因：簡報與轉錄均強調：1Q25 與 1Q26 比較口徑不同，主因 1Q26 已轉為 **IFRS 17**，與 2025 年以前的 **IFRS 4** 不具完全可比性。；1Q26 金控稅後淨利 **211 億元**，較 1Q25 的 **47 億元**顯著增加；主要來自銀行、壽險與證券子公司貢獻提升。；管理層對 2026 年銀行放款成長維持 **高個位數**看法，其中法金預期雙位數、個金高個位數；信用成本維持原先預估區間。。\n- 扣分或保留：外部總經不確定性仍高，簡報與轉錄均提及 **中東地緣政治衝突**、通膨與利率路徑變化，可能影響市場波動。；壽險投資與避險結果受匯率、利率與市場價格變動影響；1Q26 雖有正利差，但後續表現仍取決於金融市場走勢。；1Q26 起採 **IFRS 17**，與過去 IFRS 4 期間的損益、CSM、投資收益等指標可比性有限。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
