          "detailMarkdown": "## 6725 矽科宏晟 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（57 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 1、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 近年營收自 2022 年的 1,192,086 仟元，成長至 2025 年的 3,816,489 仟元；2026Q1 營收為 938,397 仟元。\n- 2025 年毛利率 23%、營業利益率 16%、稅後淨利率 11%，2026Q1 毛利率 23%、營業利益率 13%、稅後淨利率 10%。\n- 2025 年每股盈餘 12.98 元；2026Q1 EPS 2.59 元。\n- 2023–2025 年現金股利分別為 7、8、7 元；簡報註記 2026/3/11 董事會擬發放 7 元，待 2026/6/24 股東會確認。\n- 轉錄提到資本額約 3.7 億元，與簡報所列 NTD 371,300,000 相符。\n\n### 展望與成長利基\n- 簡報主軸為半導體資本支出持續成長，帶動 CDS 與建廠相關工程需求。\n- 轉錄提到 2026Q1 營收年增約 35%，並表示今年營收走勢可望較去年更佳。\n- 海外市場方面，管理層提到美國、日本、新加坡等地仍有建廠與擴廠需求。\n- 公司持續投入研發與專利布局，以強化製程技術與系統整合能力。\n- 簡報提及將透過履約品質與專案管理經驗，提升後續擴充專案承接機會。\n\n### 產品、客戶與市場位置\n- 管理層強調受惠於半導體、AI、HPC 與先進封裝帶動的建廠與製程升級需求。\n- 海外布局已涵蓋中國、美國、日本、新加坡，主打在地化服務與即時支援。\n- 簡報主軸為半導體資本支出持續成長，帶動 CDS 與建廠相關工程需求。\n- 海外市場方面，管理層提到美國、日本、新加坡等地仍有建廠與擴廠需求。\n- 海外市場如美國、日本、新加坡的在地化建置仍在初期或擴充階段，執行不確定性較高。\n- 問題二：各市場進度與壓力。回覆提到台灣、美國、日本、新加坡皆有案子，但各地缺工與建置條件不同。\n\n### 風險與不確定性\n- 轉錄多次提到建廠節奏、交期與材料到貨時間存在波動，可能影響營收認列節奏。\n- 缺工與人力招募不易被反覆提及，特別是在台灣與海外新設據點的推進上。\n- 轉錄提到材料供應、供應鏈競爭與戰事因素，可能造成缺料或成本壓力。\n- 海外市場如美國、日本、新加坡的在地化建置仍在初期或擴充階段，執行不確定性較高。\n- 前瞻性陳述與實際結果可能不同，簡報已明示風險與不確定性。\n- 簡報寫法為「CDS」，轉錄中多次口誤或混用為「CDF」；**需人工確認**，依簡報應以 CDS 為準。\n- 轉錄提及公司「去年 12 月 31 日掛牌」與「今年第一次法說會」；簡報未載明掛牌日期，**需人工確認**。\n- 轉錄多次出現「2025 年營收約 38 億」與簡報 2025 年營業收入 3,816,489 仟元相符，數值一致。\n\n### Q&A 與管理層口氣\n- 問題一：營運動能與在手訂單能見度。回覆重點為：在手案源能見度不差，但以營收作為觀察指標較貼近實際。\n- 問題二：各市場進度與壓力。回覆提到台灣、美國、日本、新加坡皆有案子，但各地缺工與建置條件不同。\n- 回覆中多次強調公司仍屬工程與設備服務業，前置備料與月結款項使資金需求偏緊。\n- 轉錄中提到配息目標希望拉高至五成以上，並預期 2025 年股利約 7 元。\n- 其他內容多為重複性口語敘述，部分段落提到與學校合作培育人才、降低缺工壓力。\n\n### 評分利基點\n- 加分主因：管理層強調受惠於半導體、AI、HPC 與先進封裝帶動的建廠與製程升級需求。；簡報亦強調 ESG、公司治理與研發量能，並列示多項專利申請。；近年營收自 2022 年的 1,192,086 仟元，成長至 2025 年的 3,816,489 仟元；2026Q1 營收為 938,397 仟元。。\n- 扣分或保留：轉錄多次提到建廠節奏、交期與材料到貨時間存在波動，可能影響營收認列節奏。；缺工與人力招募不易被反覆提及，特別是在台灣與海外新設據點的推進上。；轉錄提到材料供應、供應鏈競爭與戰事因素，可能造成缺料或成本壓力。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
