          "detailMarkdown": "## 3004 豐達科 深度法說分析\n\n### 一頁結論\n- 展望評價：正面看好（71 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 3、保守訊號 0。\n- 判讀：正向訊號較集中，通常代表公司對需求、訂單或產品組合的能見度較高。仍要確認這些動能是否能轉成營收與毛利。 \n\n### 營運與財務重點\n- 2025 年合併營收為新台幣 40.55 億元；2026 Q1 營收為新台幣 12.04 億元，年增。\n- 2026 Q1 產品組合：航太扣件 62%、航太車削件 31%、工業扣件 7%。\n- 近五年財務摘要（簡報揭露）：2025 年稅後淨利 3.31 億元、EPS 5.85 元；2024 年稅後淨利 3.76 億元、EPS 6.88 元。\n- 2025Q1 資本支出為 1.47 億元；轉述中提及 2025 年整體資本支出約 8.2 億元，且 2026 年可能與去年接近或略高。\n- 管理層說明 EPS 較去年波動，主要與稀釋、馬來西亞建置成本、匯率與原物料價格變動有關。\n\n### 展望與成長利基\n- 航太市場方面，簡報與轉述均指向窄體機、LEAP / GTF 相關需求持續；2026 年 LEAP 交付預期高於 2025 年。\n- MRO 市場需求成長，簡報提到 2026 年市場規模上修至 1,350 億美元，維修需求與備件需求同步上升。\n- 工業燃氣渦輪（IGT）與航空引擎延伸應用被視為新興機會，但目前公司占比不高。\n- 馬來西亞廠 2026 年以 NPI 開發、小量出貨與認證為主，2027 年後隨 M2 建置完成，擴產效益才較可能逐步顯現。\n- 公司表示 2026～2027 年仍會持續開發新產品，量產訂單的貢獻將較為漸進。\n\n### 產品、客戶與市場位置\n- 成長主軸包括產能與技術升級、飛安利基產品、智慧製造與智慧化經營管理，延續差異化策略。\n- 馬來西亞新廠為重要擴產與區域布局項目，2026 年仍以新產品開發與認證為主。\n- 市場面則受民航復甦、機隊老化、MRO 需求提升與地緣政治影響，帶動對航太扣件的需求延續。\n- 2026 Q1 產品組合：航太扣件 62%、航太車削件 31%、工業扣件 7%。\n- 航太市場方面，簡報與轉述均指向窄體機、LEAP / GTF 相關需求持續；2026 年 LEAP 交付預期高於 2025 年。\n- MRO 市場需求成長，簡報提到 2026 年市場規模上修至 1,350 億美元，維修需求與備件需求同步上升。\n\n### 風險與不確定性\n- 產能滿載與設備交期延長，可能造成交付壓力；轉錄提到設備交期、熱處理交期明顯拉長。\n- 原物料價格仍處高檔，且鋁材、刀具、化學原料等成本受國際情勢與供應鏈影響。\n- 地緣政治與中東衝突造成航線延長、飛行時間增加，也可能推升 MRO 與供應鏈不穩定風險。\n- 新廠與新產品仍需經過客戶認證與製程認證，認證期內對營收貢獻有限。\n- P&W / GTF 與 C919 / LEAP-1C 等機型仍有個別供應或適航不確定性，需求節奏可能波動。\n- **需人工確認：公司名稱轉錄多次誤稱為「宏達科技」**，但簡報與會議資訊顯示應為「豐達科／豐達科技」。\n- **需人工確認：地點未在轉錄中完整呈現**，以會議資訊為準為台北市南港區南港路一段209號B棟國際會議廳。\n- **需人工確認：轉錄提及「四大引擎製造商包含 Safran」與簡報第 7 頁列示內容不一致**；簡報第 6、7 頁寫為 CFM/GE、Rolls-Royce、Pratt & Whitney，未列 Safran 為獨立 OEM。\n\n### Q&A 與管理層口氣\n- 管理層表示目前沒有產能承接大量現貨急單，長約訂單優先。\n- 提到 2026 年第一季有一筆銷退約 2,000 多萬元，屬單一件號、單一客戶的退回重檢事件。\n- 公司目前主要供應商以美國與歐洲為主，材料價格談判採長約方式調整。\n- 轉述中提及各地員工分布約為：台灣 500～600 人、中國約 200 多人、馬來西亞約 70～80 人。\n- 公司目前未規劃切入軍工、半導體等非航太領域，仍以航太發動機與機身扣件／機加件為核心。\n\n### 評分利基點\n- 加分主因：成長主軸包括產能與技術升級、飛安利基產品、智慧製造與智慧化經營管理，延續差異化策略。；市場面則受民航復甦、機隊老化、MRO 需求提升與地緣政治影響，帶動對航太扣件的需求延續。；2025Q1 資本支出為 1.47 億元；轉述中提及 2025 年整體資本支出約 8.2 億元，且 2026 年可能與去年接近或略高。。\n- 扣分或保留：產能滿載與設備交期延長，可能造成交付壓力；轉錄提到設備交期、熱處理交期明顯拉長。；原物料價格仍處高檔，且鋁材、刀具、化學原料等成本受國際情勢與供應鏈影響。；地緣政治與中東衝突造成航線延長、飛行時間增加，也可能推升 MRO 與供應鏈不穩定風險。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
