      "detailMarkdown": "## 7610 聯友金屬-創 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（50 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 0、保守訊號 0。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- 2026 Q1 營業額為 **NT$1,001,764 仟元**，稅前淨利 **NT$666,352 仟元**，毛利率 **74%**。\n- 2025 年全年營業額 **NT$1,405,539 仟元**，稅前淨利 **NT$303,457 仟元**，毛利率 **31%**。\n- 最近四季數據顯示，2025 Q4 營業額 **NT$516,379 仟元**、稅前淨利 **NT$211,117 仟元**，毛利率 **50%**。\n- 轉錄中提到 2026 Q1 稅後虧損約 **489 萬元**，並說明部分虧損來自 IPO 一次性費用；該敘述與簡報僅揭露稅前淨利，**需人工確認**。\n- 轉錄另提及 Q1 營收年增約 26%、日本市場年增近 45%，以及遞延收入與多年期訂單成長；簡報未列示，**需人工確認**。\n\n### 展望與成長利基\n- 公司規劃持續推進鎢粉、碳化鎢、APT、氧化鎢等高值化產品，並擴展至合金及靶材等應用。\n- 簡報列示未來建廠時程：屏南三廠預計 **2026/6–2027/09**，屏科廠預計 **2026/9–2027/9**。\n- 轉錄中提到，公司希望從原本偏加工／原料型，逐步往下游深耕，並將客戶範圍延伸至汽車、手機等終端製造鏈，**需人工確認**。\n- 董事長亦提到子公司鎢粉產品已開始生產，但認證期仍在進行，市場需求具延續性；簡報僅寫「規劃進行中」與擴產時程。\n- 轉錄中提及 2030 年朝合金與靶材布局，屬長期願景；簡報對應為「三到五年目標」與產品擴展方向。\n\n### 產品、客戶與市場位置\n- 董事長於轉錄中補充，公司以「加工／自售雙軌」模式營運，並強調未來往下游高值化產品延伸。\n- 簡報亦揭露公司正在推進屏南三廠、屏科廠等擴產計畫，產品涵蓋鎢酸鈉、APT、氧化鎢、鎢粉、碳化鎢等。\n- 會中另提及鈷材料供應受剛果出口政策影響，全球供給偏緊，對公司鈷產品線具支撐背景。\n- 轉錄另提及 Q1 營收年增約 26%、日本市場年增近 45%，以及遞延收入與多年期訂單成長；簡報未列示，**需人工確認**。\n- 公司規劃持續推進鎢粉、碳化鎢、APT、氧化鎢等高值化產品，並擴展至合金及靶材等應用。\n- 轉錄中提到，公司希望從原本偏加工／原料型，逐步往下游深耕，並將客戶範圍延伸至汽車、手機等終端製造鏈，**需人工確認**。\n\n### 風險與不確定性\n- 鎢與鈷原料供應受中國、剛果等地政策與地緣政治影響，供應鏈集中度高。\n- 簡報指出中國鎢礦開採配額、環保管制、出口管制持續收緊，可能影響全球原料流通。\n- 鈷原料方面，剛果自 2025 年起採出口禁令／配額制，全球供給顯著收縮。\n- 轉錄中提到鎢粉、六氟化鎢等產品受出口管制與供應吃緊影響，部分下游客戶可能減產或停產；屬外部市場風險，**需人工確認**。\n- 簡報免責聲明載明前瞻性資訊可能受未來不確定性影響，實際結果可能與預期不同。\n- **公司簡介衝突：**簡報與英文版皆寫公司業務為「鎢合金／鎢、鈷金屬回收循環」，但轉錄中董事長曾口述為「鋁金屬跟鍺金屬的循環」；依簡報判定為 **需人工確認**，疑似口誤或轉錄混入其他公司內容。\n- **產品名稱衝突：**簡報主軸為鎢、鈷產品；轉錄多處出現「鋁、鍺、鉬鏡、鋁出」等詞，與簡報明顯不一致，**需人工確認**。\n- **財務口徑衝突：**簡報揭露 2026 Q1 稅前淨利 **666,352 仟元**，轉錄提到稅後虧損 **489 萬元**，兩者口徑不同且金額差異極大，**需人工確認**。\n\n### Q&A 與管理層口氣\n- 轉錄問答提及：2030 擴展至合金與靶材的純度門檻較高，需提升製程純度與認證；**需人工確認**。\n- 轉錄問答提及：子公司鎢產品認證已送件、進行中，預期完成時點未明確對外揭露；**需人工確認**。\n- 轉錄中董事長多次強調公司模式為「加工＋自售」雙軌，且加工費相對於原料價格上升時，客戶更傾向委外代工。\n- 轉錄提到公司將以循環回收效率、非中供應鏈、台灣需求穩定等作為競爭利基；簡報亦有相同論述。\n- 其他內容包含產業、國際政策與永續議題的延伸分享，未見額外量化承諾。\n\n### 評分利基點\n- 加分主因：董事長於轉錄中補充，公司以「加工／自售雙軌」模式營運，並強調未來往下游高值化產品延伸。；轉錄另提及 Q1 營收年增約 26%、日本市場年增近 45%，以及遞延收入與多年期訂單成長；簡報未列示，**需人工確認**。；公司規劃持續推進鎢粉、碳化鎢、APT、氧化鎢等高值化產品，並擴展至合金及靶材等應用。。\n- 扣分或保留：鎢與鈷原料供應受中國、剛果等地政策與地緣政治影響，供應鏈集中度高。；簡報指出中國鎢礦開採配額、環保管制、出口管制持續收緊，可能影響全球原料流通。；鈷原料方面，剛果自 2025 年起採出口禁令／配額制，全球供給顯著收縮。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
