      "detailMarkdown": "## 7823 奧義賽博-KY創 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（45 分）。\n- 資料基礎：本次尚未取得可用語音轉錄，評估主要依簡報與 MOPS 擇要訊息；若後續補入影音，分數與判讀可再更新。\n- 評分依據：正向訊號 1、保守訊號 2。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- 1Q26 營業收入 NT$91.0M，年增 26.6%；其中經常性收入年增 12.7%，專案型服務收入年增 197.6%。\n- 1Q26 毛利 NT$78.5M，毛利率 86.3%；營業利益為虧損 NT$12.9M，較 1Q25 虧損縮小。\n- 1Q26 稅後淨損 NT$4.9M，每股虧損 NT$0.15；簡報指出即便認列 IPO 一次性費用 NT$3.34M，虧損仍較前期改善。\n- 1Q26 期末現金及約當現金 NT$764.5M，佔總資產 88%；簡報並揭露 IPO 募資與營運現金流入。\n- 1Q26 期末遞延收入與多年期訂單合計 NT$363.7M，較去年同期成長 22.36%。\n\n### 展望與成長利基\n- 公司預期資安韌性、模型安全與國防安全三條產品/市場曲線並進，作為後續成長主軸。\n- 簡報指出遞延收入與多年期訂單可作為未來營收動能水庫，後續將逐月轉列營收。\n- 海外展開方面，簡報列出日本、東南亞、印度、歐洲與紐澳等合作/開拓進度。\n- 產品面持續推進 XecGuard（LLM 防火牆）、XecART（AI Red Teaming）、XecDefend（無人機防禦）等。\n- 簡報提及現金足以支應未來 4–5 年研發、海外擴張與策略投資/M&A。\n\n### 產品、客戶與市場位置\n- 公司主軸聚焦「AI 資安」與「AI 對 AI 的韌性」；簡報以「三支箭」描述成長方向：資安韌性 AI、模型韌性 AI、國防韌性 AI。\n- 公司強調其產品線涵蓋 EDR、IASM、EASM、AI/LLM 防火牆與無人機防禦等，並以平台化整合與自有 AI 技術為核心。\n- 公司預期資安韌性、模型安全與國防安全三條產品/市場曲線並進，作為後續成長主軸。\n- 海外展開方面，簡報列出日本、東南亞、印度、歐洲與紐澳等合作/開拓進度。\n- 產品面持續推進 XecGuard（LLM 防火牆）、XecART（AI Red Teaming）、XecDefend（無人機防禦）等。\n- 簡報免責聲明指出，營運展望、財務狀況與業務預測可能因市場需求、政策法規、總體經濟與其他不可控因素而改變。\n\n### 風險與不確定性\n- 簡報免責聲明指出，營運展望、財務狀況與業務預測可能因市場需求、政策法規、總體經濟與其他不可控因素而改變。\n- AI 與資安產業存在技術迭代快速、攻防手法演進及合規要求變動等不確定性。\n- 國防/無人機防禦相關業務涉及政府、軍工與法規環境，推進節奏可能受外部條件影響。\n- 海外合作與市場拓展涉及跨區域夥伴整合、落地時程與客戶導入風險。\n- 專案型收入占比上升時，營收波動與認列時點可能較不穩定。\n- **需人工確認**：會議資訊標示日期為「2026-06-23」，簡報封面與多頁標題卻寫「115年上半年 / 1Q26 / 1H26」，年份口徑不一致，推測可能是轉錄或簡報標示混用。\n- **需人工確認**：簡報第 6 頁現金部位寫 NT$764.5M，但第 51 頁現金圖表上方出現的數值與資金流示意可能對應不同期間/口徑，需確認圖表基準。\n- **需人工確認**：簡報第 48 頁對遞延收入、多年期訂單、合約負債的文字定義較長，與第 6 頁摘要的「遞延收入+多年期訂單尚未開立發票」說法略有差異，需釐清口徑。\n\n### Q&A 與管理層口氣\n- 未揭露。\n\n### 評分利基點\n- 加分主因：公司主軸聚焦「AI 資安」與「AI 對 AI 的韌性」；簡報以「三支箭」描述成長方向：資安韌性 AI、模型韌性 AI、國防韌性 AI。；公司強調其產品線涵蓋 EDR、IASM、EASM、AI/LLM 防火牆與無人機防禦等，並以平台化整合與自有 AI 技術為核心。；簡報多次提到台灣、日本與東南亞等海外布局，並強調國際組織、研調機構與獎項背書。。\n- 扣分或保留：簡報免責聲明指出，營運展望、財務狀況與業務預測可能因市場需求、政策法規、總體經濟與其他不可控因素而改變。；AI 與資安產業存在技術迭代快速、攻防手法演進及合規要求變動等不確定性。；國防/無人機防禦相關業務涉及政府、軍工與法規環境，推進節奏可能受外部條件影響。。\n- 可信度：尚缺語音轉錄，較難判斷管理層口氣、Q&A 細節與未寫在簡報中的展望。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
